.motionly-stage {
      --ink: #f8fafc;
      --muted: #94a3b8;
      --surface: #0b0f17;
      --surface-2: #131924;
      --accent: #d97757;
      position: relative;
      width: 100%;
      height: 100%;
      overflow: hidden;
      color: var(--ink);
      background: #07090f;
      font-family: Inter, ui-sans-serif, system-ui, sans-serif;
    }
    .motionly-field {
      position: absolute;
      inset: 0;
      background:
        linear-gradient(rgba(255,255,255,.025) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,.025) 1px, transparent 1px),
        radial-gradient(circle at 50% 45%, rgba(217,119,87,.14), transparent 40%);
      background-size: 80px 80px, 80px 80px, 100% 100%;
    }
    .motionly-signal {
      position: absolute;
      left: 10%;
      right: 10%;
      top: 50%;
      height: 1px;
      transform-origin: left center;
      background: linear-gradient(90deg, transparent, var(--accent), transparent);
      box-shadow: 0 0 24px rgba(217,119,87,.5);
    }
    .motionly-world {
      position: absolute;
      left: 0;
      top: 0;
      width: 7680px;
      height: 1080px;
      transform-origin: 0 0;
      will-change: transform;
    }
    .motionly-carrier {
      position: absolute;
      left: 0;
      top: 0;
      overflow: hidden;
      border: 1px solid rgba(255,255,255,.1);
      background: rgba(15,20,30,.92);
      box-shadow: 0 40px 120px rgba(0,0,0,.6), 0 0 0 1px rgba(255,255,255,.03) inset;
      transform-origin: center;
    }
    .motionly-face { position: absolute; inset: 0; }
    .motionly-hook-face {
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 40px 60px;
      text-align: center;
    }
    .motionly-hook-copy {
      margin: 0;
      max-width: 1100px;
      font-size: 64px;
      line-height: 1.05;
      letter-spacing: -.045em;
      font-weight: 750;
    }
    .motionly-chat-face,
    .motionly-proof-face {
      display: grid;
      grid-template-columns: 280px 1fr;
      background: #0d121b;
    }
    .motionly-sidebar {
      padding: 32px 24px;
      border-right: 1px solid rgba(255,255,255,.07);
      background: #111722;
    }
    .motionly-brand { font: 700 28px/1 Georgia, serif; margin-bottom: 36px; color: #fff; }
    .motionly-nav-item {
      margin: 8px 0;
      padding: 12px 14px;
      border-radius: 10px;
      color: #94a3b8;
      font-size: 15px;
    }
    .motionly-nav-item.is-active { color: white; background: rgba(255,255,255,.07); }
    .motionly-workspace { position: relative; padding: 48px 60px; overflow: hidden; }
    .motionly-kicker { color: var(--accent); font-size: 13px; font-weight: 750; letter-spacing: .15em; text-transform: uppercase; }
    .motionly-product-title { margin: 12px 0 0; font-size: 48px; line-height: 1.05; letter-spacing: -.04em; }
    .motionly-focus-rig {
      position: absolute;
      left: 60px;
      right: 60px;
      bottom: 50px;
      transform-origin: 50% 100%;
    }
    .motionly-prompt {
      position: relative;
      min-height: 180px;
      padding: 28px;
      border: 1px solid rgba(255,255,255,.12);
      border-radius: 22px;
      background: #161e2e;
      box-shadow: 0 20px 60px rgba(0,0,0,.4);
    }
    .motionly-prompt-line { max-width: 820px; font-size: 24px; line-height: 1.4; }
    .motionly-prompt-copy { font-size: 24px; line-height: 1.4; }
    .motionly-caret {
      display: inline-block;
      width: 3px;
      height: 25px;
      margin: 0;
      vertical-align: -3px;
      background: var(--accent);
    }
    .motionly-action {
      position: absolute;
      right: 24px;
      bottom: 22px;
      width: 48px;
      height: 48px;
      display: grid;
      place-items: center;
      border-radius: 14px;
      color: #fff;
      background: var(--accent);
      font-size: 20px;
      font-weight: 800;
    }
    .motionly-cursor {
      position: absolute;
      left: 0;
      top: 0;
      width: 32px;
      height: 44px;
      pointer-events: none;
      filter: drop-shadow(0 8px 20px rgba(0,0,0,.5));
    }
    .motionly-response {
      margin-top: 32px;
      max-width: 800px;
      font-size: 34px;
      line-height: 1.15;
      letter-spacing: -.03em;
      font-weight: 700;
    }
    .motionly-response-list { margin: 26px 0 0; padding: 0; max-width: 760px; list-style: none; }
    .motionly-response-line {
      margin: 0 0 12px;
      padding: 14px 18px;
      border-radius: 12px;
      background: rgba(255,255,255,.04);
      font-size: 20px;
      color: #cbd5e1;
    }
    .motionly-proof-card {
      position: absolute;
      right: 60px;
      top: 140px;
      width: 380px;
      min-height: 460px;
      padding: 28px;
      border: 1px solid rgba(255,255,255,.12);
      border-radius: 26px;
      background: linear-gradient(145deg, #1e2738, #101622);
    }
    .motionly-proof-label { color: var(--muted); font-size: 13px; letter-spacing: .12em; text-transform: uppercase; }
    .motionly-proof-value { margin-top: 16px; font-size: 70px; letter-spacing: -.055em; font-weight: 780; font-variant-numeric: tabular-nums; }
    .motionly-proof-line { height: 7px; margin-top: 18px; border-radius: 999px; background: rgba(255,255,255,.1); overflow: hidden; }
    .motionly-proof-line::after { content: ""; display: block; width: 85%; height: 100%; background: var(--accent); }
    .motionly-final-face { display: flex; align-items: center; justify-content: center; text-align: center; padding: 36px; }
    .motionly-final-copy { font-size: 48px; line-height: 1.1; letter-spacing: -.045em; font-weight: 780; }
    .motionly-final-copy strong { color: var(--accent); }

