export function buildTimeline(context) {
  const { root, timeline, register } = context;
  const get = (id) => {
    const element = root.querySelector('[data-edit="' + id + '"]');
    if (!element) {
      console.warn('Motionly: no [data-edit="' + id + '"] layer to animate.');
      return document.createElement("div");
    }
    register(id, element);
    return element;
  };
  const all = (selector) => Array.from(root.querySelectorAll(selector));

  const stage = get("stage");
  const signal = get("semantic-signal");
  const world = get("camera-world");
  const carrier = get("story-carrier");
  const hookFace = get("hook-face");
  const hookCopy = get("hook-copy");
  const chatFace = get("chat-face");
  const sidebar = get("chat-sidebar");
  const navItems = all(".motionly-chat-face .motionly-nav-item");
  const workspace = get("chat-workspace");
  const productTitle = get("product-title");
  const focusRig = get("focus-rig");
  const promptShell = get("prompt-shell");
  const promptCopy = get("prompt-copy");
  const caret = get("prompt-caret");
  const action = get("action-button");
  const cursor = get("cursor");
  const proofFace = get("proof-face");
  const response = get("response-copy");
  const responseLines = all(".motionly-response-line");
  const proofCard = get("proof-card");
  const proofValue = get("proof-value");
  const finalFace = get("final-face");
  const finalCopy = get("final-copy");

  const typeText = (target, text, start, duration) => {
    timeline.set(target, { textContent: "" }, 0);
    timeline.set(target, { textContent: "" }, start);
    const state = { count: 0 };
    timeline.fromTo(
      state,
      { count: 0 },
      {
        count: text.length,
        duration: duration,
        ease: "steps(" + text.length + ")",
        onUpdate: () => {
          target.textContent = text.slice(0, Math.round(state.count));
        },
      },
      start,
    );
  };

  // --- Time 0: Initial Layout ---
  timeline.set(stage, { autoAlpha: 1 }, 0);
  timeline.set(world, { x: 0, y: 0, scale: 1 }, 0);
  timeline.set(carrier, { x: 340, y: 390, width: 1240, height: 300, borderRadius: 28, background: "rgba(15,20,30,0)", borderColor: "rgba(255,255,255,0)", boxShadow: "0 0 0 rgba(0,0,0,0)" }, 0);
  timeline.set(hookFace, { display: "flex", autoAlpha: 1 }, 0);
  timeline.set(chatFace, { display: "none", autoAlpha: 0 }, 0);
  timeline.set(proofFace, { display: "none", autoAlpha: 0 }, 0);
  timeline.set(finalFace, { display: "none", autoAlpha: 0 }, 0);
  timeline.set(signal, { scaleX: 0, autoAlpha: .35 }, 0);
  timeline.set(focusRig, { scale: 1 }, 0);
  timeline.set(caret, { autoAlpha: 0 }, 0);
  timeline.set(cursor, { x: 1300, y: 1020, scale: 1, autoAlpha: 0 }, 0);
  timeline.set(proofCard, { autoAlpha: 0 }, 0);

  // --- scene-01 (0.0 - 5.5): Hook & Editorial Setup ---
  continuousTextGradient(hookCopy, "linear-gradient(90deg, #fff 0%, #d97757 60%, #a78bfa 100%)");
  giantKineticCrop(timeline, hookCopy, { at: 0.2, startScale: 2.1, endScale: 1, duration: 1.4, unit: "words", stagger: .08, settleEase: "back.out(1.35)" });
  timeline.to(signal, { scaleX: 1, duration: 4.2, ease: "power2.inOut" }, .4);
  timeline.to(carrier, { y: 375, duration: 2.5, ease: "sine.inOut" }, 1.5);

  // --- scene-02 (5.5 - 12.0): Morph Handoff & Typing Interaction ---
  timeline.set(chatFace, { display: "grid", autoAlpha: 0 }, 5.38);
  morph(timeline, carrier, { x: 2100, y: 120, width: 1520, height: 840, borderRadius: 32, background: "rgba(15,20,30,.98)", borderColor: "rgba(255,255,255,.12)", boxShadow: "0 40px 120px rgba(0,0,0,.6)" }, { at: 5.5, duration: 1.25, ease: "expo.inOut" });
  timeline.to(world, { x: -1920, y: 0, scale: 1, duration: 1.25, ease: "expo.inOut" }, 5.5);
  timeline.to(hookFace, { autoAlpha: 0, duration: .35, ease: "power2.in" }, 5.52);
  timeline.to(chatFace, { autoAlpha: 1, duration: .45, ease: "power2.out" }, 5.62);
  timeline.set(hookFace, { display: "none" }, 5.9);

  timeline.fromTo(sidebar, { x: -80, autoAlpha: 0 }, { x: 0, autoAlpha: 1, duration: .85, ease: "power4.out" }, 5.7);
  timeline.fromTo(navItems, { x: -24, autoAlpha: 0 }, { x: 0, autoAlpha: 1, duration: .55, stagger: .08, ease: "power3.out" }, 5.85);
  timeline.fromTo(workspace, { y: 50, autoAlpha: 0 }, { y: 0, autoAlpha: 1, duration: .95, ease: "power4.out" }, 6.0);
  wordSlideRotate(timeline, productTitle, { at: 6.25, distance: 36, stagger: .06, rotation: 1.8, duration: .7, ease: "back.out(1.25)" });
  timeline.fromTo(promptShell, { y: 68, autoAlpha: 0, scale: .97 }, { y: 0, autoAlpha: 1, scale: 1, duration: 1.0, ease: "back.out(1.25)" }, 6.6);

  timeline.to(caret, { autoAlpha: 1, duration: .1 }, 7.5);
  typeText(promptCopy, "Refactor authentication middleware and optimize database queries", 7.6, 2.1);
  timeline.to(world, { x: -2040, y: -25, duration: 2.1, ease: "sine.inOut" }, 7.6);

  timeline.to(world, { x: -3360, y: -580, scale: 1.4, duration: 1.0, ease: "expo.inOut" }, 9.9);
  timeline.fromTo(cursor, { x: 1300, y: 1020, autoAlpha: 0 }, { x: 1080, y: 680, autoAlpha: 1, duration: .8, ease: "power3.inOut" }, 10.05);
  timeline.to(cursor, { scale: .85, duration: .08, yoyo: true, repeat: 1, ease: "power2.inOut" }, 10.85);
  timeline.to(action, { scale: .9, duration: .09, yoyo: true, repeat: 1, ease: "back.out(1.4)" }, 10.87);
  timeline.to(caret, { autoAlpha: 0, duration: .1 }, 10.95);
  timeline.to(signal, { autoAlpha: .7, scaleX: .7, duration: .75, ease: "power3.out" }, 10.9);

  // --- scene-03 (12.0 - 17.5): Proof & Structured Output ---
  timeline.set(proofFace, { display: "grid", autoAlpha: 0 }, 11.75);
  timeline.to([promptShell, productTitle], { y: -42, autoAlpha: 0, duration: .5, ease: "power3.in" }, 11.8);
  timeline.to(cursor, { y: 880, autoAlpha: 0, duration: .45, ease: "power2.in" }, 11.82);
  morph(timeline, carrier, { x: 4100, y: 120, width: 1520, height: 840, borderRadius: 32 }, { at: 12.0, duration: 1.2, ease: "expo.inOut" });
  timeline.to(world, { x: -3840, y: 0, scale: 1, duration: 1.2, ease: "expo.inOut" }, 12.0);
  timeline.to(chatFace, { autoAlpha: 0, duration: .35, ease: "power2.in" }, 11.95);
  timeline.to(proofFace, { autoAlpha: 1, duration: .45, ease: "power2.out" }, 12.05);
  timeline.set(chatFace, { display: "none" }, 12.35);

  wordSlideRotate(timeline, response, { at: 12.3, distance: 42, stagger: .06, rotation: 1.2, duration: .75, ease: "back.out(1.3)" });
  timeline.fromTo(responseLines, { y: 24, autoAlpha: 0 }, { y: 0, autoAlpha: 1, duration: .55, stagger: .12, ease: "power3.out" }, 12.95);

  timeline.set(proofCard, { autoAlpha: 1 }, 13.4);
  timeline.fromTo(proofCard, { y: 30, scale: 0.95, autoAlpha: 0 }, { y: 0, scale: 1, autoAlpha: 1, duration: 1.0, ease: "power4.out" }, 13.4);

  const state = { count: 0 };
  timeline.fromTo(state, { count: 0 }, {
    count: 98,
    duration: 1.4,
    ease: "power2.inOut",
    onUpdate: () => {
      proofValue.textContent = Math.round(state.count) + "%";
    }
  }, 13.8);

  timeline.to(world, { x: -3900, y: -18, scale: 1.04, duration: 2.2, ease: "sine.inOut" }, 14.3);

  // --- scene-04 (17.5 - 22.0): Closing Brand Resolve ---
  timeline.set(finalFace, { display: "flex", autoAlpha: 0 }, 17.25);
  timeline.to(responseLines, { y: -28, autoAlpha: 0, duration: .4, stagger: -.05, ease: "power3.in" }, 17.3);
  timeline.to([response, proofCard], { y: -32, autoAlpha: 0, duration: .45, ease: "power3.in" }, 17.35);

  morph(timeline, carrier, { x: 4510, y: 418, width: 680, height: 244, borderRadius: 122 }, { at: 17.5, duration: 1.2, ease: "expo.inOut" });
  timeline.to(world, { x: -3840, y: 0, scale: 1, duration: 1.2, ease: "expo.inOut" }, 17.5);
  timeline.to(proofFace, { autoAlpha: 0, duration: .32, ease: "power2.in" }, 17.45);
  timeline.to(finalFace, { autoAlpha: 1, duration: .45, ease: "power2.out" }, 17.5);
  timeline.set(proofFace, { display: "none" }, 17.78);

  charSpringBounce(timeline, finalCopy, { at: 17.65, distance: 38, stagger: .03, duration: .6, ease: "back.out(1.4)" });
  timeline.to(signal, { scaleX: .18, autoAlpha: .75, duration: 1.0, ease: "power3.inOut" }, 18.2);
  timeline.to(carrier, { scale: 1.015, duration: 2.5, ease: "sine.inOut" }, 19.0);
  timeline.to({}, { duration: .2 }, 21.8);
}

