import { defineComposition, type CompositionContext } from '@motionly/runtime';
import compositionHtml from './composition.html?raw';
import compositionStyles from "./styles.css?raw";

const compositionSource = compositionHtml.replace(
  /(<template\b[^>]*>)/i,
  `$1<style>\n${compositionStyles}\n</style>`,
);
import compositionStyles from './styles.css?raw';
import { buildTimeline } from './timeline.js';

const compositionSource = compositionSource.replace(
  /(<template\b[^>]*>)/i,
  `$1<style>\n${compositionStyles}\n</style>`,
);

function mount(context: CompositionContext) {
  const documentNode = new DOMParser().parseFromString(compositionSource, 'text/html');
  const template = documentNode.querySelector<HTMLTemplateElement>('template');
  if (!template) throw new Error('Motionly template was not found.');
  context.root.replaceChildren(template.content.cloneNode(true));
}

export default defineComposition({
  id: "dynamic-comp-chat",
  title: "User Chatting to Claude",
  description: 'AI-edited Motionly composition',
  width: 1920,
  height: 1080,
  fps: 60,
  duration: 22,
  scenes: [{"id":"scene-01","label":"Prompt Initiation","start":0,"duration":5.5,"accent":"#d97757"},{"id":"scene-02","label":"Thinking & Streaming","start":5.5,"duration":6.5,"accent":"#d97757"},{"id":"scene-03","label":"Structured Artifact","start":12,"duration":5.5,"accent":"#d97757"},{"id":"scene-04","label":"Closing Promise","start":17.5,"duration":4.5,"accent":"#d97757"}],
  sourcePreview: compositionSource,
  build(context) { mount(context); buildTimeline(context); },
});
